from fastapi.testclient import TestClient
from app.main import app
def test_unconfigured_executor_fails_closed():
 c=TestClient(app); n=c.post('/api/novels',json={'title':'执行'}).json(); nid=n['id']; c.post(f'/api/novels/{nid}/chapters',json={'title':'一','content':'a'}); s=c.post(f'/api/novels/{nid}/screenplays',json={}).json(); u=f"/api/novels/{nid}/screenplays/{s['id']}"; c.post(u+'/approve'); c.post(u+'/shots'); c.post(u+'/shots/approve'); c.post(u+'/storyboard'); c.post(u+'/storyboard/approve'); c.post(u+'/assets'); c.post(u+'/assets/approve'); q=c.post(u+'/asset-tasks').json(); t=q['asset_tasks'][0]; c.put(u+f"/asset-tasks/{t['id']}",json={'status':'RUNNING','provider_id':'x','model_id':'y'}); result=c.post(u+f"/asset-tasks/{t['id']}/execute").json(); assert result['asset_tasks'][0]['status']=='FAILED'; assert 'not configured' in result['asset_tasks'][0]['error']
